head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정   
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:150px; background-color:var(--ws-gray-300);" 
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);   

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp    
    );

    strTarget += '<xf:select ' + strNameSpace + ' ' + cList + ' appearance="minimal" ref="">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:item>';
    strTarget += '<xf:label><![CDATA[multiselect1]]></xf:label>';
    strTarget += '<xf:value><![CDATA[1]]></xf:value>';
    strTarget += '</xf:item>';
    strTarget += '<xf:item>';
    strTarget += '<xf:label><![CDATA[multiselect2]]></xf:label>';
    strTarget += '<xf:value><![CDATA[2]]></xf:value>';
    strTarget += '</xf:item>';
    strTarget += '<xf:item>';
    strTarget += '<xf:label><![CDATA[multiselect3]]></xf:label>';
    strTarget += '<xf:value><![CDATA[3]]></xf:value>';
    strTarget += '</xf:item>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:select>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "multiselect",
        strTarget,
        parent1
    );
}
